const challenges = [
  {level:1,topic:'FILTRER',title:'Trouve les ventes qui comptent.',prompt:'Garde uniquement les lignes où le montant est supérieur à 400.',code:"df[df['montant'] > 400]",checks:[/df\s*\[\s*df\s*\[\s*['\"]montant['\"]\s*\]\s*>\s*400\s*\]/,/df\.query\s*\(\s*['\"].*montant\s*>\s*400.*['\"]\s*\)/],hint:'Écris d’abord une condition sur df[\'montant\'], puis place-la entre les crochets de df.',concept:'Idée-clé : une condition produit une série de True / False.',success:'Tu as isolé les observations qui répondent à ton critère.',xp:20,headers:['ville','produit','montant'],rows:[['Kinshasa','Thé','420'],['Goma','Café','680'],['Bukavu','Jus','245'],['Matadi','Thé','510']]},
  {level:1,topic:'SÉLECTIONNER',title:'Allège le tableau.',prompt:'Le marketing ne veut voir que les colonnes ville et montant, dans cet ordre.',code:"df[['ville', 'montant']]",checks:[/df\s*\[\s*\[\s*['\"]ville['\"]\s*,\s*['\"]montant['\"]\s*\]\s*\]/],hint:'Plusieurs colonnes se sélectionnent avec une liste, donc deux paires de crochets.',concept:'Idée-clé : df[\'col\'] retourne une série ; df[[\'col\']] garde un DataFrame.',success:'Tu sais maintenant viser précisément les variables utiles.',xp:20,headers:['ville','produit','montant'],rows:[['Kinshasa','Thé','420'],['Goma','Café','680'],['Bukavu','Jus','245'],['Matadi','Thé','510']]},
  {level:2,topic:'NETTOYER',title:'Répare le trou dans les données.',prompt:'Le montant manquant doit devenir 0 avant tout calcul. Complète la colonne montant.',code:"df['montant'] = df['montant'].fillna(0)",checks:[/df\s*\[\s*['\"]montant['\"]\s*\]\s*=\s*df\s*\[\s*['\"]montant['\"]\s*\]\s*\.fillna\s*\(\s*0\s*\)/,/df\.fillna\s*\(\s*\{\s*['\"]montant['\"]\s*:\s*0\s*\}\s*\)/],hint:'fillna(0) remplace les valeurs absentes. Tu peux le faire sur la colonne elle-même.',concept:'Idée-clé : un NaN n’est pas un zéro — il faut décider quoi en faire.',success:'Bien joué. Tes futures sommes ne seront plus surprises par un NaN.',xp:25,headers:['ville','montant','vendeur'],rows:[['Kinshasa','420','Mia'],['Goma','—','Nora'],['Bukavu','245','Mia'],['Matadi','510','Nora']]},
  {level:2,topic:'CRÉER',title:'Ajoute une information utile.',prompt:'Crée une colonne commission égale à 10 % du montant, sans modifier les autres colonnes.',code:"df['commission'] = df['montant'] * 0.1",checks:[/df\s*\[\s*['\"]commission['\"]\s*\]\s*=\s*df\s*\[\s*['\"]montant['\"]\s*\]\s*\*\s*0?\.1/],hint:'Une nouvelle colonne s’écrit simplement dans df[\'nom\']. Les opérations sont vectorisées.',concept:'Idée-clé : pandas calcule toute la colonne d’un seul geste.',success:'Exact. Tu as enrichi ton DataFrame sans boucle.',xp:25,headers:['ville','montant','commission'],rows:[['Kinshasa','420','?'],['Goma','680','?'],['Bukavu','245','?'],['Matadi','510','?']]},
  {level:3,topic:'RÉSUMER',title:'Qui vend le plus ?',prompt:'Calcule le total des montants pour chaque vendeur.',code:"df.groupby('vendeur')['montant'].sum()",checks:[/df\.groupby\s*\(\s*['\"]vendeur['\"]\s*\)\s*\[\s*['\"]montant['\"]\s*\]\s*\.sum\s*\(\s*\)/,/df\.groupby\s*\(\s*['\"]vendeur['\"]\s*\)\s*\.agg\s*\(/],hint:'Groupe d’abord par vendeur, choisis montant, puis appelle sum().',concept:'Idée-clé : groupby découpe le tableau avant d’appliquer une fonction.',success:'Voilà une agrégation : une réponse par groupe, plutôt qu’une ligne par vente.',xp:30,headers:['vendeur','montant','ville'],rows:[['Mia','420','Kinshasa'],['Nora','680','Goma'],['Mia','245','Bukavu'],['Nora','510','Matadi']]},
  {level:3,topic:'TRIER',title:'Place le meilleur en premier.',prompt:'Trie le DataFrame par montant, du plus grand au plus petit.',code:"df.sort_values('montant', ascending=False)",checks:[/df\.sort_values\s*\(\s*['\"]montant['\"]\s*,\s*ascending\s*=\s*false\s*\)/i],hint:'sort_values trie par ordre croissant par défaut. Quel argument inverse cet ordre ?',concept:'Idée-clé : les paramètres nommés rendent le code explicite.',success:'Oui. Tu sais produire un classement lisible instantanément.',xp:25,headers:['ville','montant'],rows:[['Kinshasa','420'],['Goma','680'],['Bukavu','245'],['Matadi','510']]},
  {level:4,topic:'RELIER',title:'Réunis les deux mondes.',prompt:'Ajoute le nom de chaque ville aux ventes via ville_id. Garde toutes les ventes.',code:"pd.merge(ventes, villes, how='left', on='ville_id')",checks:[/pd\.merge\s*\(\s*ventes\s*,\s*villes\s*,\s*how\s*=\s*['\"]left['\"]\s*,\s*on\s*=\s*['\"]ville_id['\"]\s*\)/,/ventes\.merge\s*\(\s*villes\s*,\s*how\s*=\s*['\"]left['\"]\s*,\s*on\s*=\s*['\"]ville_id['\"]\s*\)/],hint:'Une jointure left garde toutes les lignes de la table qui est à gauche.',concept:'Idée-clé : une clé est le pont entre deux tables.',success:'Parfait. Tu as enrichi les ventes sans perdre une seule ligne.',xp:35,headers:['ville_id','montant','ville'],rows:[['1','420','Kinshasa'],['2','680','Goma'],['3','245','—'],['2','510','Goma']]},
  {level:4,topic:'DATES',title:'Lis le calendrier.',prompt:'La colonne date est déjà au format datetime. Crée une colonne trimestre.',code:"df['trimestre'] = df['date'].dt.quarter",checks:[/df\s*\[\s*['\"]trimestre['\"]\s*\]\s*=\s*df\s*\[\s*['\"]date['\"]\s*\]\.dt\.quarter/],hint:'L’accesseur .dt ouvre les composants de date, dont quarter.',concept:'Idée-clé : une date contient beaucoup plus d’informations qu’un texte.',success:'Tu viens de transformer le temps en variable analysable.',xp:30,headers:['date','montant','trimestre'],rows:[['2026-01-18','420','?'],['2026-04-02','680','?'],['2026-09-11','245','?'],['2026-12-27','510','?']]},
  {level:5,topic:'TEXTE',title:'Donne une forme aux mots.',prompt:'Normalise la colonne produit afin que chaque mot commence par une majuscule.',code:"df['produit'] = df['produit'].str.title()",checks:[/df\s*\[\s*['\"]produit['\"]\s*\]\s*=\s*df\s*\[\s*['\"]produit['\"]\s*\]\.str\.title\s*\(\s*\)/],hint:'Les opérations de texte vectorisées se trouvent derrière l’accesseur .str.',concept:'Idée-clé : .str applique une opération à chaque cellule texte.',success:'Propre. Tes catégories sont enfin comparables.',xp:30,headers:['produit','montant'],rows:[['café noir','420'],['THÉ VERT','680'],['jus mangue','245'],['CAFE LATTE','510']]},
  {level:5,topic:'MAÎTRISER',title:'Compose ton premier pipeline.',prompt:'Garde les ventes supérieures à 400, puis trie-les par montant décroissant.',code:"df.query('montant > 400').sort_values('montant', ascending=False)",checks:[/query\s*\(\s*['\"].*montant\s*>\s*400.*['\"]\s*\)\s*\.sort_values\s*\(\s*['\"]montant['\"]\s*,\s*ascending\s*=\s*false\s*\)/i,/df\s*\[\s*df\s*\[\s*['\"]montant['\"]\s*\]\s*>\s*400\s*\]\s*\.sort_values\s*\(\s*['\"]montant['\"]\s*,\s*ascending\s*=\s*false\s*\)/i],hint:'Commence par le filtre ; enchaîne ensuite .sort_values(..., ascending=False).',concept:'Idée-clé : les chaînes de méthodes racontent une suite d’intentions.',success:'Niveau final validé. Tu sais déjà construire une mini-analyse lisible.',xp:50,headers:['ville','montant','produit'],rows:[['Kinshasa','420','Thé'],['Goma','680','Café'],['Bukavu','245','Jus'],['Matadi','510','Thé']]}
];
const levelNames=['Premiers pas','Mettre au propre','Faire parler les données','Relier les indices','Penser en pipeline'];
const stored=JSON.parse(localStorage.getItem('pandasQuestSolo')||'{"solved":[],"xp":0,"current":0}');
let current=Math.min(stored.current||0,challenges.length-1);const $=id=>document.getElementById(id);const clean=value=>value.toLowerCase().replace(/\s+/g,'').replace(/`/g,'');
function renderTable(c){$('dataTable').innerHTML=`<table><thead><tr>${c.headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${c.rows.map(r=>`<tr>${r.map((cell,index)=>`<td class="${(index===c.headers.length-1&&cell==='?')||cell==='—'?'emphasis-cell':''}">${cell}</td>`).join('')}</tr>`).join('')}</tbody></table>`;$('rowCount').textContent=`${c.rows.length} lignes`;}
function updateProgress(){const completed=stored.solved.length;const level=Math.min(5,Math.floor(current/2)+1);$('xp').textContent=stored.xp;$('progressLine').style.width=`${Math.max(5,completed/challenges.length*100)}%`;$('stepLabel').textContent=`Défi ${current+1} sur ${challenges.length}`;$('levelName').textContent=`Niveau ${level} · ${levelNames[level-1]}`;$('chapterLabel').textContent=`Chapitre ${level} / 5 — ${levelNames[level-1]}`;$('levelDots').innerHTML=levelNames.map((_,i)=>`<i class="${i+1<level?'done':i+1===level?'active':''}"></i>`).join('');}
function resetFeedback(){const box=$('feedback');box.className='feedback';box.innerHTML='<span class="feedback-symbol">✦</span><p>Chaque essai te rapproche de la bonne intuition.</p>';}
function render(){const c=challenges[current];$('levelTag').textContent=`NIVEAU ${String(c.level).padStart(2,'0')}`;$('topic').textContent=c.topic;$('title').textContent=c.title;$('prompt').textContent=c.prompt;$('answerInput').value='';$('answerInput').placeholder='# écris ta solution';$('hintText').textContent='';$('hintBtn').dataset.open='false';$('microConcept').textContent=c.concept;renderTable(c);updateProgress();resetFeedback();}
function save(){stored.current=current;localStorage.setItem('pandasQuestSolo',JSON.stringify(stored));}
function showFeedback(type,text){const box=$('feedback');box.className=`feedback ${type}`;box.innerHTML=`<span class="feedback-symbol">${type==='error'?'!':'✓'}</span><p>${text}</p>`;}
function win(){const c=challenges[current];const first=!stored.solved.includes(current);if(first){stored.solved.push(current);stored.xp+=c.xp;save();}$('earnedXp').textContent=c.xp;$('successTitle').textContent=current===challenges.length-1?'Le parcours est à toi.':'C’est exactement ça.';$('successBody').textContent=current===challenges.length-1?'Tu as relié les gestes essentiels de pandas en un seul chemin clair.':' '+c.success;$('successKicker').textContent=current===challenges.length-1?'PARCOURS TERMINÉ':'CONCEPT COMPRIS';const count=stored.solved.length;$('streakText').textContent=`${count} défi${count>1?'s':''} compris`;$('successOverlay').classList.add('visible');$('successOverlay').setAttribute('aria-hidden','false');showFeedback('success','Bien vu. La logique est correcte.');updateProgress();}
function verify(){const c=challenges[current],answer=clean($('answerInput').value);if(c.checks.some(pattern=>pattern.test(answer))){win()}else{showFeedback('error','Presque. Relis le verbe demandé et regarde la structure de tes crochets ou parenthèses.');}}
function next(){if(current<challenges.length-1){current++;save();render()}else{current=0;save();render();toast('Nouveau tour : rejoue les concepts pour les automatiser.');}$('successOverlay').classList.remove('visible');$('successOverlay').setAttribute('aria-hidden','true');}
function toast(text){const el=$('toast');el.textContent=text;el.classList.add('show');clearTimeout(window.toastTime);window.toastTime=setTimeout(()=>el.classList.remove('show'),2500);}
$('checkBtn').addEventListener('click',verify);$('answerInput').addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='Enter'){e.preventDefault();verify();}});$('hintBtn').addEventListener('click',()=>{const open=$('hintBtn').dataset.open==='true';$('hintText').textContent=open?'':challenges[current].hint;$('hintBtn').dataset.open=String(!open);});$('continueBtn').addEventListener('click',next);$('skipBtn').addEventListener('click',()=>{current=(current+1)%challenges.length;save();render();toast('Défi suivant chargé.');});$('resetBtn').addEventListener('click',()=>{if(confirm('Réinitialiser ta progression locale ?')){localStorage.removeItem('pandasQuestSolo');location.reload();}});render();
